package com.nexusdrive.metadata.service.impl;import com.nexusdrive.common.exception.*;import com.nexusdrive.metadata.dto.*;import com.nexusdrive.metadata.entity.*;import com.nexusdrive.metadata.repository.*;import com.nexusdrive.metadata.service.FolderService;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service@Transactional public class FolderServiceImpl implements FolderService{private final FolderRepository folders;private final FileMetadataRepository files;public FolderServiceImpl(FolderRepository f,FileMetadataRepository m){folders=f;files=m;}public Folder create(UUID o,FolderRequest r){Folder p=parent(o,r.parentId());Folder f=new Folder();f.setOwnerId(o);f.setParent(p);f.setName(clean(r.name()));f.setFullPath((p==null?"":p.getFullPath())+"/"+f.getName());return folders.save(f);}public Folder update(UUID o,UUID id,FolderRequest r){Folder f=get(o,id),p=parent(o,r.parentId());if(p!=null&&(p.getId().equals(id)||p.getFullPath().startsWith(f.getFullPath()+"/")))throw new ValidationException("Cannot move folder into itself");String old=f.getFullPath();f.setName(clean(r.name()));f.setParent(p);f.setFullPath((p==null?"":p.getFullPath())+"/"+f.getName());Folder saved=folders.save(f);folders.findAll().stream().filter(x->x.getOwnerId().equals(o)&&x.getFullPath().startsWith(old+"/")).forEach(x->x.setFullPath(saved.getFullPath()+x.getFullPath().substring(old.length())));return saved;}public void delete(UUID o,UUID id){folders.delete(get(o,id));}public FolderContentsResponse contents(UUID o,UUID id){get(o,id);return new FolderContentsResponse(folders.findByOwnerIdAndParentId(o,id).stream().map(FolderResponse::from).toList(),files.findByOwnerIdAndFolderIdAndStatus(o,id,FileMetadata.Status.ACTIVE).stream().map(FileResponse::from).toList());}private Folder get(UUID o,UUID id){return folders.findByIdAndOwnerId(id,o).orElseThrow(()->new ResourceNotFoundException("Folder not found"));}private Folder parent(UUID o,UUID id){return id==null?null:get(o,id);}private String clean(String n){String s=n.trim();if(s.contains("/")||s.contains("\\")||s.equals(".")||s.equals(".."))throw new ValidationException("Invalid folder name");return s;}}
